{
    return n == 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * n);
}
float easeInOutExpo(float x)
{
    return x == 0.0
      ? 0.0
      : x == 1.0
      ? 1.0
      : x < 0.5 ? pow(2.0, 20.0 * x - 10.0) / 2.0
      : (2.0 - pow(2.0, -20.0 * x + 10.0)) / 2.0;
}
float stepped(float n, float c)
{
    return floor(n / c) * c;
}
void mainImage( out vec4 fragColor, vec2 uv )
{
    float time = threshold * explosionTime;
    float explosionLerp = time / explosionTime;
    float explosionLerpInverted = 1.0 - explosionLerp;
    float outerRingPosition = easeOutExpo(explosionLerp);
    float innerRingPosition = easeInOutExpo(explosionLerp);
    float outerRingNoise = texture(mainTexture, vec2(uv.x * .1 + outerRingPosition, uv.y * .1)).r;
    outerRingPosition += (outerRingNoiseIntensity / 2.0) - (outerRingNoise * outerRingNoiseIntensity);
    outerRingPosition -= outerRingNoise * pow(explosionLerp, 3.0) * outerRingNoiseIntensity * 10.0;
    float angleFromCenter = atan(uv.y - 0.5, uv.x - 0.5);
    float insideRingTexture = texture(mainTexture, vec2(
        angleFromCenter / 7.0 + cc_time.x * .2 + outerRingPosition * .1,
        cc_time.x * .013)
    ).r;
    innerRingPosition -= insideRingTexture * insideRingTexture * explosionLerpInverted * 8.0 * (.9 - outerRingPosition);
    float distanceFromCenter = (distance(vec2(0.5, 0.5), uv.xy) * 2.0);
    float insideGradient = (distanceFromCenter - innerRingPosition) / outerRingPosition;
    insideGradient *= insideRingTexture;
    insideGradient += explosionLerpInverted * .3;
    insideGradient += insideGradient*insideGradient*insideGradient / 1.5;
    insideGradient += .1;
    insideGradient = stepped(insideGradient, 0.1);
    float isInsideRing = 1.0 - sign((distanceFromCenter - innerRingPosition) * (distanceFromCenter - outerRingPosition));
    isInsideRing *= sign(insideGradient);
    vec3 alphaMap = vec3(isInsideRing, isInsideRing, isInsideRing);
    vec3 colorMap = vec3(insideGradient * (2.0 + insideGradient), insideGradient * (1.0 + insideGradient), insideGradient);
    vec3 bgColor = vec3(sin(cc_time.x) * .5, sin(cc_time.x + 1.2) * .5, cos(cc_time.x) * .5);
    vec3 color = vec3(0.);
    color = alphaMap * colorMap;
    fragColor = vec4(color, isInsideRing);
}
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  mainImage(o, uv0);
  o *= color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

